pub fn floor_div(a: i64, b: i64) -> i64 {
    let q = a / b;
    let r = a % b;
    let adjust = r != 0 && ((r > 0) != (b > 0));
    if adjust { q - 1 } else { q }
}

pub fn remainder(a: i64, b: i64) -> i64 {
    let q = a / b;
    let r = a % b;
    let adjust = r != 0 && ((r > 0) != (b > 0));
    if adjust { r + b } else { r }
}

